: "208 775", "America/Regina": "306 639", "America/Chicago|America/Denver|America/North_Dakota/Center": "605 701", "America/Jamaica": "658 876", "America/Puerto_Rico": "787 939", "America/Nassau": "242", "America/Barbados": "246", "America/Edmonton|America/Vancouver": "250", "America/Anguilla": "264", "America/Antigua": "268", "America/Tortola": "284", "America/St_Thomas": "340", "America/Cayman": "345", "America/Halifax|America/Toronto": "418", "Atlantic/Bermuda": "441", "America/Grenada": "473", "America/Denver|America/Los_Angeles": "541", "America/Grand_Turk": "649", "America/Montserrat": "664", "Pacific/Saipan": "670", "Pacific/Guam": "671", "Pacific/Pago_Pago": "684", "America/Halifax|America/St_Johns": "709", "America/Lower_Princes": "721", "America/St_Lucia": "758", "America/Dominica": "767", "America/St_Vincent": "784", "America/Toronto|America/Winnipeg": "807", "Pacific/Honolulu": "808", "America/Edmonton|America/Fort_Nelson|America/Toronto|America/Vancouver|America/Winnipeg": "867", "America/Port_of_Spain": "868", "America/St_Kitts": "869", "America/Puerto_Rico|America/St_Johns": "879", "America/Adak|America/Anchorage|America/Juneau|Pacific/Honolulu": "907", "America/Denver|America/Phoenix": "928", "America/Boise|America/Los_Angeles": "986"};
const areaTz = {};
for (const [zones, codes] of Object.entries(AREA)) {
  for (const c of codes.split(' ')) areaTz[c] = zones.split('|');
}
const DACH_TZ = { DE: 'Europe/Berlin', AT: 'Europe/Vienna', CH: 'Europe/Zurich' };
const DIAL = { '49': 'DE', '43': 'AT', '41': 'CH' };
const COUNTRY_ALIASES = {
  US: 'US', USA: 'US', 'UNITED STATES': 'US', 'UNITED STATES OF AMERICA': 'US',
  DE: 'DE', DEU: 'DE', GERMANY: 'DE', DEUTSCHLAND: 'DE',
  AT: 'AT', AUT: 'AT', AUSTRIA: 'AT', 'ÖSTERREICH': 'AT', OESTERREICH: 'AT',
  CH: 'CH', CHE: 'CH', SWITZERLAND: 'CH', SCHWEIZ: 'CH', SUISSE: 'CH',
  CA: 'CA', CAN: 'CA', CANADA: 'CA',
};
const TOLL_FREE = ['800', '833', '844', '855', '866', '877', '888'];

return $input.all().map((item) => {
  const payload = item.json.body ?? item.json;
  const lead = payload.lead ?? {};

  let country = COUNTRY_ALIASES[String(lead.country ?? '').trim().toUpperCase()] ?? null;
  const rawCountry = lead.country ?? null;

  // Phone: work out the country calling code and, for +1, the area code.
  let phone = String(lead.phone ?? '').replace(/[^\d+]/g, '');
  if (phone.startsWith('00')) phone = '+' + phone.slice(2);
  let areaCode = null;
  let phoneCountry = null;
  if (phone.startsWith('+1') && phone.length >= 5) {
    areaCode = phone.slice(2, 5);
  } else if (phone.startsWith('+')) {
    phoneCountry = DIAL[phone.slice(1, 3)] ?? null;
  } else if (!rawCountry || country === 'US' || country === 'CA') {
    const d = phone.replace(/^1(?=\d{10}$)/, '');
    if (d.length === 10) areaCode = d.slice(0, 3);
  }
  if (TOLL_FREE.includes(areaCode)) areaCode = null;
  const phoneZones = areaCode ? areaTz[areaCode] ?? [] : [];

  // Fill a missing country from the phone, then from the email TLD.
  if (!country && !rawCountry) {
    const tld = String(lead.email ?? '').split('.').pop().toUpperCase();
    country = phoneCountry ?? (phoneZones.length ? 'US' : null) ?? (DACH_TZ[tld] ? tld : null);
  }

  const tz = { timezone: null, source: null, confidence: 'none', candidates: phoneZones };
  if (DACH_TZ[country]) {
    Object.assign(tz, { timezone: DACH_TZ[country], source: 'country', confidence: 'high' });
  } else if (phoneZones.length === 1) {
    Object.assign(tz, { timezone: phoneZones[0], source: 'phone_area_code', confidence: 'medium' });
  }

  return {
    json: {
      event: payload.event ?? null,
      delivery_id: payload.delivery_id ?? null,
      test: payload.test ?? false,
      lead,
      country,
      tz,
      // Erased leads are never sent to a third-party enrichment API.
      needs_enrichment: !tz.timezone && !lead.erased,
    },
  };
});

