// Step 2 - use the Apollo match: person location first, company HQ second,
// then fall back to the phone candidates and finally a country default.
const STATES = {
  AL: ['Alabama', 'America/Chicago'], AK: ['Alaska', 'America/Anchorage'],
  AZ: ['Arizona', 'America/Phoenix'], AR: ['Arkansas', 'America/Chicago'],
  CA: ['California', 'America/Los_Angeles'], CO: ['Colorado', 'America/Denver'],
  CT: ['Connecticut', 'America/New_York'], DE: ['Delaware', 'America/New_York'],
  DC: ['District of Columbia', 'America/New_York'],
  FL: ['Florida', 'America/New_York', 'America/Chicago'],
  GA: ['Georgia', 'America/New_York'], HI: ['Hawaii', 'Pacific/Honolulu'],
  ID: ['Idaho', 'America/Boise', 'America/Los_Angeles'],
  IL: ['Illinois', 'America/Chicago'],
  IN: ['Indiana', 'America/Indiana/Indianapolis', 'America/Chicago'],
  IA: ['Iowa', 'America/Chicago'], KS: ['Kansas', 'America/Chicago', 'America/Denver'],
  KY: ['Kentucky', 'America/New_York', 'America/Chicago'],
  LA: ['Louisiana', 'America/Chicago'], ME: ['Maine', 'America/New_York'],
  MD: ['Maryland', 'America/New_York'], MA: ['Massachusetts', 'America/New_York'],
  MI: ['Michigan', 'America/Detroit', 'America/Chicago'],
  MN: ['Minnesota', 'America/Chicago'], MS: ['Mississippi', 'America/Chicago'],
  MO: ['Missouri', 'America/Chicago'], MT: ['Montana', 'America/Denver'],
  NE: ['Nebraska', 'America/Chicago', 'America/Denver'],
  NV: ['Nevada', 'America/Los_Angeles', 'America/Denver'],
  NH: ['New Hampshire', 'America/New_York'], NJ: ['New Jersey', 'America/New_York'],
  NM: ['New Mexico', 'America/Denver'], NY: ['New York', 'America/New_York'],
  NC: ['North Carolina', 'America/New_York'],
  ND: ['North Dakota', 'America/Chicago', 'America/Denver'],
  OH: ['Ohio', 'America/New_York'], OK: ['Oklahoma', 'America/Chicago'],
  OR: ['Oregon', 'America/Los_Angeles', 'America/Boise'],
  PA: ['Pennsylvania', 'America/New_York'], RI: ['Rhode Island', 'America/New_York'],
  SC: ['South Carolina', 'America/New_York'],
  SD: ['South Dakota', 'America/Chicago', 'America/Denver'],
  TN: ['Tennessee', 'America/Chicago', 'America/New_York'],
  TX: ['Texas', 'America/Chicago', 'America/Denver'],
  UT: ['Utah', 'America/Denver'], VT: ['Vermont', 'America/New_York'],
  VA: ['Virginia', 'America/New_York'], WA: ['Washington', 'America/Los_Angeles'],
  WV: ['West Virginia', 'America/New_York'], WI: ['Wisconsin', 'America/Chicago'],
  WY: ['Wyoming', 'America/Denver'],
};
const stateZones = {};
for (const [abbr, [name, ...zones]] of Object.entries(STATES)) {
  stateZones[abbr] = zones;
  stateZones[name.toUpperCase()] = zones;
}
const DACH_TZ = {
  DE: 'Europe/Berlin', GERMANY: 'Europe/Berlin', DEUTSCHLAND: 'Europe/Berlin',
  AT: 'Europe/Vienna', AUSTRIA: 'Europe/Vienna',
  CH: 'Europe/Zurich', SWITZERLAND: 'Europe/Zurich',
};
const US_NAMES = ['US', 'USA', 'UNITED STATES', 'UNITED STATES OF AMERICA'];
const norm = (v) => String(v ?? '').trim().toUpperCase();
const validZone = (z) => {
  try { new Intl.DateTimeFormat('en-US', { timeZone: z }); return true; } catch (e) { return false; }
};

// Resolve one Apollo location record (person or organization).
function fromLocation(loc, candidates, leadCountry) {
  if (!loc) return null;
  const country = norm(loc.country);
  if (DACH_TZ[country]) return { timezone: DACH_TZ[country], split: false };
  const isUS = US_NAMES.includes(country) || (!country && leadCountry === 'US');
  const zones = isUS ? stateZones[norm(loc.state)] : null;
  if (!zones) return null;
  // State spans two zones: let the phone area code break the tie.
  const overlap = zones.filter((z) => candidates.includes(z));
  const match = overlap.length === 1 ? overlap[0] : null;
  return { timezone: match ?? zones[0], split: zones.length > 1 && !match };
}

const previous = $('Resolve from country + phone').all();

return $input.all().map((item, i) => {
  const base = (previous[i] ?? previous[0]).json;
  const person = item.json.person ?? {};
  const org = person.organization ?? item.json.organization ?? {};
  const candidates = base.tz.candidates ?? [];
  const tz = { ...base.tz };
  const set = (timezone, source, confidence) => Object.assign(tz, { timezone, source, confidence });

  const personLoc = fromLocation(person, candidates, base.country);
  const orgLoc = fromLocation(org, candidates, base.country);

  if (person.time_zone && validZone(person.time_zone)) {
    set(person.time_zone, 'apollo_person', 'high');
  } else if (personLoc) {
    set(personLoc.timezone, 'apollo_person', personLoc.split ? 'medium' : 'high');
  } else if (orgLoc) {
    set(orgLoc.timezone, 'apollo_company_hq', orgLoc.split ? 'low' : 'medium');
  } else if (candidates.length) {
    set(candidates[0], 'phone_area_code', 'low');
  } else if (base.country === 'US') {
    set('America/New_York', 'default', 'low');
  }

  const location = {
    city: person.city ?? org.city ?? null,
    state: person.state ?? org.state ?? null,
    country: person.country ?? org.country ?? null,
  };
  return {
    json: {
      ...base,
      tz,
      location,
      apollo_matched: Boolean(item.json.person),
      apollo_error: item.json.error ? String(item.json.error.message ?? item.json.error) : null,
    },
  };
});

// Step 3 - one flat record for the CRM / Slack / booking step that follows.
const DACH = ['Europe/Berlin', 'Europe/Vienna', 'Europe/Zurich'];

return $input.all().map((item) => {
  const { lead, tz, country, location } = item.json;
  const zone = tz.timezone;
  const now = new Date();
  let utcOffset = null, localTime = null, businessHours = null;
  if (zone) {
    const part = (opts, type) => new Intl.DateTimeFormat('en-US', { timeZone: zone, ...opts })
      .formatToParts(now).find((p) => p.type === type).value;
    utcOffset = part({ timeZoneName: 'longOffset' }, 'timeZoneName').replace('GMT', 'UTC');
    if (utcOffset === 'UTC') utcOffset = 'UTC+00:00';
    localTime = now.toLocaleString('sv-SE', { timeZone: zone }).slice(0, 16);
    const hour = Number(localTime.slice(11, 13));
    const weekday = part({ weekday: 'short' }, 'weekday');
    businessHours = !['Sat', 'Sun'].includes(weekday) && hour >= 9 && hour < 17;
  }
  let region = 'unknown';
  if (DACH.includes(zone) || ['DE', 'AT', 'CH'].includes(country)) region = 'DACH';
  else if (country === 'US' || (zone && /^(America|Pacific)\//.test(zone))) region = country === 'CA' ? 'CA' : 'US';
  else if (country || lead.country) region = 'other';

  return {
    json: {
      delivery_id: item.json.delivery_id,
      test: item.json.test,
      person_id: lead.person_id ?? null,
      name: lead.name ?? null,
      email: lead.email ?? null,
      company_name: lead.company_name ?? null,
      region,
      country: country ?? lead.country ?? null,
      state: location?.state ?? null,
      city: location?.city ?? null,
      timezone: zone,
      utc_offset: utcOffset,
      timezone_source: tz.source,
      timezone_confidence: tz.confidence,
      lead_local_time: localTime,
      lead_in_business_hours: businessHours,
      lead,
    },
  };
});
